svg.script:
(() => {
  const svg = document.documentElement;
  const clamp = (v,a,b) => Math.max(a, Math.min(b,v));
  const emit = (name, detail) => {
    svg.dispatchEvent(new CustomEvent(name, { detail, bubbles:true }));
    // Compatibility aliases for host apps.
    const aliases = {
      "stem-fader":"faderchange",
      "stem-button":"buttonchange",
      "stem-rocker":"rockerchange"
    };
    if (aliases[name]) svg.dispatchEvent(new CustomEvent(aliases[name], { detail, bubbles:true }));
  };

  const svgPoint = (clientX, clientY) => {
    const p = svg.createSVGPoint();
    p.x = clientX; p.y = clientY;
    return p.matrixTransform(svg.getScreenCTM().inverse());
  };

  // ---------------- FADERS ----------------
  const originalCY = 428;
  const top = 424;
  const bottom = 518;

  document.querySelectorAll('.fader-hit').forEach(hit => {
    const ch = Number(hit.dataset.channel);
    const layer = document.getElementById(`fader-layer-${ch}`);
    let dragging = false;

    function setValue(value, source="pointer") {
      value = clamp(value, 0, 1);
      const targetCY = bottom - value * (bottom-top);
      const dy = targetCY - originalCY;
      layer.setAttribute('transform', `translate(0 ${dy.toFixed(3)})`);
      hit.dataset.value = String(value);
      hit.setAttribute('aria-valuenow', String(Math.round(value*100)));
      emit('stem-fader', { channel:ch, value, source });
    }

    function fromEvent(e) {
      const p = svgPoint(e.clientX, e.clientY);
      const value = 1 - ((p.y-top)/(bottom-top));
      setValue(value);
    }

    hit.addEventListener('pointerdown', e => {
      dragging = true;
      hit.setPointerCapture(e.pointerId);
      fromEvent(e);
    });
    hit.addEventListener('pointermove', e => { if (dragging) fromEvent(e); });
    hit.addEventListener('pointerup', e => {
      dragging=false;
      try{hit.releasePointerCapture(e.pointerId)}catch{}
    });
    hit.addEventListener('pointercancel', () => dragging=false);

    hit.addEventListener('keydown', e => {
      let v = Number(hit.dataset.value || 1);
      if (e.key==="ArrowUp" || e.key==="ArrowRight") v += .025;
      else if (e.key==="ArrowDown" || e.key==="ArrowLeft") v -= .025;
      else if (e.key==="Home") v = 0;
      else if (e.key==="End") v = 1;
      else return;
      e.preventDefault();
      setValue(v, "keyboard");
    });

    // Host API: element.setStemValue(0..1)
    hit.setStemValue = v => setValue(Number(v), "api");
  });

  // ---------------- BUTTONS ----------------
  document.querySelectorAll('[id^="button-hit-"]').forEach(hit => {
    const ch = Number(hit.dataset.channel);
    const layer = document.getElementById(`button-layer-${ch}`);
    let active = false;

    const pressVisual = () => {
      layer.setAttribute('transform', 'translate(0 2.4) scale(0.985 0.97)');
      layer.style.transformOrigin = 'center';
      layer.classList.add('pressed');
    };
    const releaseVisual = () => {
      layer.setAttribute('transform', 'translate(0 0)');
      layer.classList.remove('pressed');
    };

    hit.addEventListener('pointerdown', e => {
      hit.setPointerCapture(e.pointerId);
      pressVisual();
    });
    hit.addEventListener('pointerup', e => {
      releaseVisual();
      active = !active;
      hit.setAttribute('aria-pressed', String(active));
      emit('stem-button', { channel:ch, active });
      try{hit.releasePointerCapture(e.pointerId)}catch{}
    });
    hit.addEventListener('pointercancel', releaseVisual);

    hit.addEventListener('keydown', e => {
      if (e.key===" " || e.key==="Enter") {
        e.preventDefault();
        pressVisual();
        setTimeout(() => {
          releaseVisual();
          active = !active;
          hit.setAttribute('aria-pressed', String(active));
          emit('stem-button', { channel:ch, active });
        }, 90);
      }
    });

    // Host API: element.setStemActive(bool)
    hit.setStemActive = v => {
      active = !!v;
      hit.setAttribute('aria-pressed', String(active));
    };
  });

  // ---------------- SIDE ROCKER ----------------
  const rockerHit = document.getElementById('rocker-hit');
  const rockerLayer = document.getElementById('rocker-layer');
  let rockerHeld = false;

  function setRocker(v, source="pointer") {
    v = v < 0 ? -1 : v > 0 ? 1 : 0;
    rockerHit.setAttribute('aria-valuenow', String(v));
    // Tiny movement of the exact photographed part.
    rockerLayer.setAttribute('transform', `translate(0 ${v * -3})`);
    emit('stem-rocker', { value:v, source });
  }

  rockerHit.addEventListener('pointerdown', e => {
    rockerHeld = true;
    rockerHit.setPointerCapture(e.pointerId);
    const p = svgPoint(e.clientX,e.clientY);
    const box = rockerHit.getBBox();
    setRocker(p.y < box.y + box.height/2 ? 1 : -1);
  });
  rockerHit.addEventListener('pointerup', e => {
    rockerHeld = false;
    setRocker(0);
    try{rockerHit.releasePointerCapture(e.pointerId)}catch{}
  });
  rockerHit.addEventListener('pointercancel', () => {
    rockerHeld=false; setRocker(0);
  });
  rockerHit.addEventListener('keydown', e => {
    if (e.key==="ArrowUp") { e.preventDefault(); setRocker(1,"keyboard"); }
    else if (e.key==="ArrowDown") { e.preventDefault(); setRocker(-1,"keyboard"); }
    else if (e.key===" " || e.key==="Enter" || e.key==="Escape") {
      e.preventDefault(); setRocker(0,"keyboard");
    }
  });

  // ---------------- PUBLIC HOST API ----------------
  // Inline SVG usage:
  // svg.addEventListener('stem-fader', e => audio.setGain(e.detail.channel, e.detail.value))
  // svg.addEventListener('stem-button', e => audio.toggleStem(e.detail.channel, e.detail.active))
  // svg.addEventListener('stem-rocker', e => transport.setRocker(e.detail.value))
  svg.stemTape = {
    setFader(channel, value) {
      document.getElementById(`fader-hit-${channel}`)?.setStemValue(value);
    },
    setButton(channel, active) {
      document.getElementById(`button-hit-${channel}`)?.setStemActive(active);
    },
    setRocker(value) { setRocker(value, "api"); }
  };
})();
